/// PCCC status text.
pub(crate) fn pccc_error(code: i32) -> Option<&'static str> {
    match code {
        -20 => Some("No Data Returned"),
        -8 => Some("No data returned from PLC"),
        -7 => Some("No data specified to data link layer"),
        -6 => Some("Could Not Open Com Port"),
        -5 => Some("Invalid Address"),
        -4 => Some("Unknown Message from DataLink Layer"),
        -3 => Some("No Reponse, Check COM Settings"),
        -2 => Some("Not Acknowledged (NAK)"),
        16 => Some(
            "Illegal Command or Format, Address may not exist or not enough elements in data file",
        ),
        32 => Some("PLC Has a Problem and Will Not Communicate"),
        48 => Some("Remote Node Host is Missing, Disconnected, or Shut Down"),
        64 => Some("Host Could Not Complete Function Due To Hardware Fault"),
        80 => Some("Addressing problem or Memory Protect Rungs"),
        96 => Some("Function not allows due to command protection selection"),
        112 => Some("Processor is in Program mode"),
        128 => Some("Compatibility mode file missing or communication zone problem"),
        144 => Some("Remote node cannot buffer command"),
        240 => Some("Error code in EXT STS Byte"),
        _ => None,
    }
}
